tests_src:
def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_nonnegative(run, x):
    out = run(x)
    cost = int(out.strip())
    assert cost >= 0, 'Cost must be nonnegative'

def test_ge_n_minus_1(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    assert cost >= n-1, f'Cost {cost} must be at least n-1 = {n-1}'

def test_le_sum_first_n_minus_1(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    max_cost = n * (n - 1) // 2
    assert cost <= max_cost, f'Cost {cost} exceeds worst-case sum of prices 1..{n-1} = {max_cost}'

def test_v_eq_one(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    if v == 1:
        expected = n * (n - 1) // 2
        assert cost == expected, f'For v=1, cost must be sum of 1..{n-1} = {expected}, got {cost}'

def test_v_ge_n_minus_one(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    if v >= n - 1:
        assert cost == n - 1, f'For v >= n-1, cost must be {n-1}, got {cost}'

def test_examples(run, x):
    out = run(x)
    if x == '4 2\n':
        assert out.strip() == '4', f'Example 4 2 expects 4, got {out.strip()}'
    if x == '7 6\n':
        assert out.strip() == '6', f'Example 7 6 expects 6, got {out.strip()}'

def test_dp_small_n(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    if n > 15:
        return
    INF = 10**9
    dp = [[INF] * (v + 1) for _ in range(n + 1)]
    dp[1][0] = 0
    for i in range(1, n):
        for f in range(v + 1):
            if dp[i][f] == INF:
                continue
            for k in range(v - f + 1):
                new_f = f + k
                cost_add = k * i
                for j in range(i + 1, n + 1):
                    dist = j - i
                    if dist > new_f:
                        break
                    new_fuel = new_f - dist
                    if new_fuel > v:
                        continue
                    dp[j][new_fuel] = min(dp[j][new_fuel], dp[i][f] + cost_add)
    ans = min(dp[n][f] for f in range(v + 1))
    assert cost == ans, f'DP optimal cost is {ans}, got {cost}'

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit(), 'Output must be a nonnegative integer'
    assert out == s + '\n' or out == s, 'Output should be integer optionally followed by newline'

def test_n2_always_one(run, x):
    n, v = map(int, x.strip().split())
    out = run(x)
    cost = int(out.strip())
    if n == 2:
        assert cost == 1, f'For n=2, cost must be 1, got {cost}'
